-- Seed of rsg.change_log, 16 Nov 2026: every theme/rsg-core live deploy (git tags) + known site, tracking and Google events.
-- Run once (guarded: does nothing if a deploy.sh-sourced live tag is already in the table).
DO $do$ BEGIN IF EXISTS (SELECT 1 FROM rsg.change_log WHERE ref LIKE 'live-2026%') THEN RAISE NOTICE 'already seeded'; RETURN; END IF;
INSERT INTO rsg.change_log (at, kind, title, details, ref, source) VALUES ('2026-11-11T08:09:49+00:00', 'deploy', 'Theme/rsg-core deploy to live', $q$- deploy.sh: ssh -n so the confirmation prompt gets its answer
