INSERT INTO rsg.change_log (at, kind, title, details, ref, source) VALUES ('2026-11-15T10:40:57+00:00', 'deploy', 'Theme/rsg-core deploy to live', $q$- Merchant logos for AU: Running Warehouse AU, adidas (optical set, dfs/app/tools/logos/optical.py; existing logos byte-identical)
- Homepage: 'Brands buying guides' -> 'Reviews by brand' (guides cleanup 15 Nov). The 8 brand cards link to the brand's review listing (get_term_link = /reviews/<brand>/all/) instead of the retired brand guide; bottom button '+ All reviews' -> /reviews/.
